"""Build an offline-capable public page using aggregate current-run results only."""
from pathlib import Path
import base64, json, html
import pandas as pd
import plotly.express as px
from plotly.offline import get_plotlyjs

ROOT=Path(__file__).resolve().parents[1]; CUR=ROOT/'outputs/current'; OUT=CUR/'chapter4_infrastructure'
labels={'U0':'Baseline','U1':'Electrification','U2':'Fabric','U3':'Fabric + electrification','U4':'Electrification + PV','U5':'Fabric + electrification + PV'}
palette=['#72777d','#b25b38','#7b9853','#277f8e','#d5a43f','#695a8c']
finance=pd.read_csv(OUT/'finance_summary.csv'); finance['Scenario']=finance.scenario.str[:2]
infra=pd.read_csv(OUT/'all_scenario_summary.csv').rename(columns={'scenario':'Scenario'})
sc=pd.read_csv(CUR/'scenarios/scenario_summary.csv');sc=sc.loc[sc.scope.eq('planning_wards')].copy();sc['Scenario']=sc.scenario.str[:2]
stats=json.loads((OUT/'finance_refresh_stats.json').read_text()); metrics=json.loads((CUR/'baseline/metrics.json').read_text())
run=json.loads((CUR/'completion.json').read_text())
def chart(frame,x,y,title,unit,stack=False):
    fig=px.bar(frame,x=x,y=y,title=title,barmode='stack' if stack else 'group',color_discrete_sequence=palette,
               labels={'value':unit,'variable':'Series',y:unit} if isinstance(y,str) else {'value':unit,'variable':'Funding'})
    fig.update_layout(template='plotly_white',height=360,margin=dict(l=60,r=25,t=65,b=50),font=dict(family='Arial',size=13))
    return fig.to_html(full_html=False,include_plotlyjs=False,config={'displaylogo':False,'responsive':True})
def table(frame):return '<div class="tablewrap">'+frame.to_html(index=False,border=0,float_format=lambda x:f'{x:,.2f}',classes='data')+'</div>'
def image(name,caption):
    raw=base64.b64encode((OUT/'figures'/name).read_bytes()).decode()
    return '<figure><img src="data:image/png;base64,'+raw+'" alt="'+html.escape(caption)+'"><figcaption>'+caption+'</figcaption></figure>'
f=finance.rename(columns={'net_capex_MGBP':'Net investment','incentives_MGBP':'Support'})
priority=pd.DataFrame(stats['priority_25pct']).T.reset_index().rename(columns={'index':'Priority','dwellings':'Dwellings','carbon_kt':'Carbon saved (kt/year)','net_budget_MGBP':'Budget used (£m)'})
sections=[]
sections.append('<section id="scenarios"><h2>Six planning scenarios</h2><p>28,663 dwellings in ten Guildford wards. Scenarios apply fixed packages rather than forecasting adoption.</p><div class="key">'+''.join(f'<span><b>{k}</b> {v}</span>' for k,v in labels.items())+'</div><div class="grid">'+chart(sc,'Scenario','carbon_kt','Operational emissions','ktCO₂e/year')+chart(sc,'Scenario','bills_MGBP','Annual energy expenditure','£ million/year')+'</div>'+table(sc[['Scenario','delivered_gas_GWh','elec_net_GWh','carbon_kt','bills_MGBP']].rename(columns={'delivered_gas_GWh':'Gas (GWh)','elec_net_GWh':'Net electricity (GWh)','carbon_kt':'Emissions (ktCO₂e)','bills_MGBP':'Bills (£m)'}))+'<p class="note">Bills and emissions retain the annual 45% PV self-consumption assumption and configured 2021 prices and carbon factors. Hourly cell imports below use a separate accounting boundary.</p></section>')
sections.append('<section id="finance"><h2>Revised support and net investment</h2><p>Support changes upfront cost, payback and priority rankings. Energy demand is unchanged because scenario adoption is fixed.</p>'+chart(f,'Scenario',['Net investment','Support'],'Gross investment split between net cost and support','£ million',True)+table(finance[['Scenario','capex_gross_MGBP','incentives_MGBP','net_capex_MGBP']].rename(columns={'capex_gross_MGBP':'Gross (£m)','incentives_MGBP':'Support (£m)','net_capex_MGBP':'Net (£m)'}))+f'<div class="cards"><div><b>£278.38m</b><span>U5 net investment</span></div><div><b>{stats["payback_ok_pct"]:.1f}%</b><span>U5 payback ≤12.5 years</span></div><div><b>{stats["group_A_dwellings"]:,}</b><span>Highest benefit–cost group</span></div></div><h3>At 25% of the net intervention budget</h3>'+table(priority)+image('refresh_figure6.png','Ward outcomes under the revised support assumptions.')+image('refresh_figure9bcd.png','Carbon-to-net-cost ranking, finite simple payback and rented tenure.')+'</section>')
sections.append('<section id="infrastructure"><h2>Local infrastructure and hourly imports</h2><p>28,662 mapped dwellings; 271 rated secondary-substation cells. One unassigned dwelling is excluded consistently. PV capacity is capped at 4 kWp per dwelling allocation.</p>'+image('scenario_infrastructure.png','Separate cell imports and exports, simultaneous import peak and import screening exceedances.')+table(infra[['Scenario','cell_import_GWh','cell_export_GWh','coincident_cell_import_peak_MW','cells_above_import_rating_screen','cells_above_export_rating_screen']].rename(columns={'cell_import_GWh':'Imports (GWh)','cell_export_GWh':'Exports (GWh)','coincident_cell_import_peak_MW':'Import peak (MW)','cells_above_import_rating_screen':'Import exceedances','cells_above_export_rating_screen':'Export exceedances'}))+'<p>U5 imports 140.98 GWh/year, 30.5% below electrification alone. Its 92.45 MW winter peak is unchanged by PV, which produces no electricity at the peak hour. Fabric improvement reduces that peak by 16.3% relative to electrification alone.</p>'+image('scenario_screening_maps.png','Peak residential imports divided by recorded kVA rating × 0.95; common colour scale.')+'<p class="note">Voronoi assignments are inferred, and only represented residential loads are included. Screening exceedances are not verified transformer overloads. No battery, export curtailment, network losses or inverter clipping is assumed. The annual-normalised PV profile is south-facing at 35°.</p></section>')
sections.append(f'<section id="validation"><h2>Demand model and validation</h2><p>The uncalibrated model uses typical construction properties, three size representatives and three sampled household realisations per size. The annual borough comparison has gas WAPE {metrics["gas_WAPE_pct"]:.2f}% and electricity WAPE {metrics["elec_WAPE_pct"]:.2f}%. Annual area agreement does not establish dwelling-level or hourly accuracy.</p></section>')
rules=[['BUS','New ASHP; non-social rented','£7,500 + £1,500 for oil/LPG replacement; limited to ASHP cost'],['Low-income fabric','Non-social; EPC D–G; LSOA fuel poverty ≥12% OR IMD decile ≤3','90% up to £10,000; cavity, IWI, loft, flat roof and draught proofing'],['Social housing','Social rented; EPC D–G','50% up to £7,500; eligible fabric including glazing and ASHP'],['GBIS proxy','Non-social; EPC D–G; floor area <120 m²; not low-income eligible','75% up to £1,500; cavity and loft']]
sections.append('<section id="methods"><h2>Support assumptions and provenance</h2>'+table(pd.DataFrame(rules,columns=['Proxy','Eligibility used','Amount and scope']))+'<p>Each measure receives support from at most one scheme. These are study rules, not verified programme entitlements. Missing EPC bands are inferred from certified SAP within construction and age groups, with broader fallbacks; 7,551 planning dwellings (26.3%) use imputation. Later support amounts are combined with the retained 2021 operating-cost basis.</p><p>Sources: completed scenario outputs; incentives_2026.json; the executed secondary-substation notebook; financial and infrastructure refresh summaries. This page contains aggregate results only.</p></section>')
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>EnerMap | Current scenario results</title><style>
*{box-sizing:border-box}body{margin:0;background:#f5f7f7;color:#21353d;font:16px/1.65 Arial,sans-serif}header{background:#173d49;color:white;padding:52px max(5vw,24px)}header h1{font-size:42px;line-height:1.1;margin:8px 0}header p{max-width:800px}nav{display:flex;gap:22px;flex-wrap:wrap;padding:18px 5vw;background:white;border-bottom:1px solid #d9e4e5}nav a{color:#286977;text-decoration:none;font-weight:bold}main{max-width:1240px;margin:auto;padding:24px}section{background:white;padding:32px;margin:24px 0;border:1px solid #e0e8e8;border-radius:12px;scroll-margin-top:18px}h2{font-size:28px;margin-top:0}h3{font-size:21px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;min-width:0}.grid>div{min-width:0}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:25px 0}.cards div{background:#eaf3f2;padding:20px;border-radius:8px}.cards b{font-size:30px;display:block}.cards span{display:block}.tablewrap{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:14px;text-align:left}th,td{padding:12px;border-bottom:1px solid #e0e8e8}th{background:#edf3f3;text-align:left}.key{display:flex;flex-wrap:wrap;gap:10px}.key span{padding:8px;background:#f0f4f5;border-radius:5px}.note{background:#f4f1e8;padding:15px;border-left:3px solid #b59353;font-size:14px}figure{margin:25px 0}img{width:100%;height:auto}figcaption{font-size:14px;color:#536970}footer{padding:30px;text-align:center;color:#526970}@media(max-width:800px){.grid,.cards{grid-template-columns:1fr}section{padding:18px}header h1{font-size:32px}}</style><script>'''+get_plotlyjs()+'''</script></head><body><header><div>GUILDFORD · LOCAL AREA ENERGY PLANNING</div><h1>EnerMap scenario results</h1><p>Electrification, fabric retrofit and rooftop PV: investment, energy imports and local infrastructure.</p><p>Current engine run: '''+run['completed_utc'][:10]+''' · Updated support representation</p></header><nav>'''+''.join(f'<a href="#{a}">{b}</a>' for a,b in [('scenarios','Scenarios'),('finance','Investment'),('infrastructure','Infrastructure'),('validation','Validation'),('methods','Assumptions')])+'''</nav><main>'''+''.join(sections)+'''</main><footer>EnerMap · Reproducible scenario comparisons, not forecasts of uptake.</footer></body></html>'''
for name in ['index.html','enermap_results.html']:(Path(__file__).parent/name).write_text(page,encoding='utf-8')
print('Built current aggregate results page:',Path(__file__).parent/'index.html')
